import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.immutable.ImmutableDexFile;import org.jf.dexlib2.writer.pool.DexPool;
public class ReplaceDexClass{public static void main(String[] a)throws Exception{var old=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));var replacement=DexFileFactory.loadDexContainer(new File(a[1]),Opcodes.forApi(28));Map<String,ClassDef> defs=new HashMap<>();for(String n:replacement.getDexEntryNames())for(ClassDef c:replacement.getEntry(n).getDexFile().getClasses())defs.put(c.getType(),c);for(String n:old.getDexEntryNames()){List<ClassDef> all=new ArrayList<>();int changes=0;for(ClassDef c:old.getEntry(n).getDexFile().getClasses()){ClassDef found=defs.get(c.getType());if(found==null)all.add(c);if(found!=null)changes++;}if(changes>0){DexPool.writeTo(a[2],new ImmutableDexFile(Opcodes.forApi(28),all));System.out.println("Moved "+changes+" replacement class out of "+n+" into separate patch DEX");return;}}throw new AssertionError("No replacement");}}
